import React, { useEffect, useState } from 'react';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:4000/api';

function BookingConfirmation({ title, selectedDateLong, selectedTime, bookingData, eventTypeId }) {
  const [isSubmitting, setIsSubmitting] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const saveBooking = async () => {
      try {
        // Parse the selected date and time
        const dateTimeString = `${selectedDateLong} ${selectedTime}`;
        const scheduledAt = new Date(dateTimeString).toISOString();

        const payload = {
          event_type_id: eventTypeId,
          name: bookingData.name,
          email: bookingData.email,
          notes: bookingData.notes || '',
          scheduled_at: scheduledAt,
        };

        const response = await fetch(`${API_BASE}/bookings`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(payload),
        });

        if (!response.ok) {
          throw new Error('Failed to save booking');
        }

        setIsSubmitting(false);
      } catch (err) {
        console.error('Booking save failed:', err);
        setError('Failed to save booking. Please try again.');
        setIsSubmitting(false);
      }
    };

    if (eventTypeId) {
      saveBooking();
    } else {
      setIsSubmitting(false);
    }
  }, [title, selectedDateLong, selectedTime, bookingData, eventTypeId]);

  if (isSubmitting) {
    return (
      <div className="booking-page">
        <div className="booking-confirm">
          <h2>Saving your booking...</h2>
          <p className="booking-confirm-lead">Please wait while we confirm your meeting.</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="booking-page">
        <div className="booking-confirm">
          <h2>Booking Error</h2>
          <p className="booking-confirm-lead">{error}</p>
          <div className="booking-summary">
            <p>
              <strong>Event:</strong> {title}
            </p>
            <p>
              <strong>When:</strong> {selectedDateLong} at {selectedTime}
            </p>
            <p>
              <strong>Who:</strong> {bookingData.name} ({bookingData.email})
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="booking-page">
      <div className="booking-confirm">
        <h2>Confirmed!</h2>
        <p className="booking-confirm-lead">You are scheduled with the host.</p>
        <div className="booking-summary">
          <p>
            <strong>Event:</strong> {title}
          </p>
          <p>
            <strong>When:</strong> {selectedDateLong} at {selectedTime}
          </p>
          <p>
            <strong>Who:</strong> {bookingData.name} ({bookingData.email})
          </p>
          {bookingData.notes ? (
            <p>
              <strong>Notes:</strong> {bookingData.notes}
            </p>
          ) : null}
        </div>
      </div>
    </div>
  );
}

export default BookingConfirmation;
